package com.yeshoda.medical.service;
import com.yeshoda.medical.dto.*; import com.yeshoda.medical.model.User; import com.yeshoda.medical.repository.UserRepository; import com.yeshoda.medical.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository repo;private final PasswordEncoder encoder;private final JwtService jwt; public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;encoder=e;jwt=j;}
 public AuthResponse register(RegisterRequest r){if(repo.findByEmail(r.email()).isPresent())throw new RuntimeException("Email already registered");User u=new User(r.name(),r.email(),encoder.encode(r.password()),"PATIENT");repo.save(u);return new AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail(),u.getRole());}
 public AuthResponse login(AuthRequest r){User u=repo.findByEmail(r.email()).orElseThrow(()->new RuntimeException("Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new RuntimeException("Invalid email or password");return new AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail(),u.getRole());}}
